// Check all 185 dynamic keys are accounted for in en, de, fr
for (const key of dynamicKeys) {
  if (!enDynamic[key]) throw new Error(`Missing dynamic EN for: "${key}"`);
  if (!deDynamic[key]) throw new Error(`Missing dynamic DE for: "${key}"`);
  if (!frDynamic[key]) throw new Error(`Missing dynamic FR for: "${key}"`);

  const keyPh = [...key.matchAll(/\{n\d\}/g)].map(m => m[0]).sort();
  for (const [lang, dict] of [['en', enDynamic], ['de', deDynamic], ['fr', frDynamic]]) {
    const transPh = [...dict[key].matchAll(/\{n\d\}/g)].map(m => m[0]).sort();
    if (JSON.stringify(keyPh) !== JSON.stringify(transPh)) {
      throw new Error(`Placeholder mismatch for "${key}" in ${lang}: expected ${JSON.stringify(keyPh)}, got ${JSON.stringify(transPh)}`);
    }
  }
}

// Load existing cockpit.js
import existingCockpit from '../src/locales/cockpit.js';

const merged = {
  en: { ...existingCockpit.en, ...enDynamic },
  de: { ...existingCockpit.de, ...deDynamic },
  fr: { ...existingCockpit.fr, ...frDynamic }
};

const output = `// Autogenerated and verified catalog of mayoral cockpit, scenario benchmarks, dynamic advisors and systemic dynamics translations.
export default ${JSON.stringify(merged, null, 2)};
`;

fs.writeFileSync('src/locales/cockpit.js', output, 'utf8');
console.log(`Successfully merged cockpit catalog: ${Object.keys(merged.en).length} total verified keys in each language.`);
